<?php
namespace App\Http\Controllers; use App\Data\OrderData; use App\Enums\OrderPriority; use App\Http\Requests\StoreOrderRequest; use App\Http\Resources\OrderResource; use App\Models\Order; use App\Repositories\OrderRepository; use App\Services\OrderService; use Illuminate\Http\RedirectResponse; use Inertia\Inertia; use Inertia\Response;
class OrderController extends Controller { public function index(OrderRepository $orders): Response { $this->authorize('viewAny', Order::class); return Inertia::render('Orders/Index', ['orders'=>OrderResource::collection($orders->paginateFor(request()->user()))]); } public function create(): Response { $this->authorize('create', Order::class); return Inertia::render('Orders/Create', ['priorities'=>array_column(OrderPriority::cases(),'value')]); } public function store(StoreOrderRequest $request, OrderService $service): RedirectResponse { $order = $service->create(new OrderData($request->user()->id, $request->string('title'), $request->string('description'), $request->date('deadline')->toDateTimeString(), OrderPriority::from($request->string('priority')), (float)$request->input('total_price'), null, (float)$request->input('worker_fee',0))); foreach($request->file('files', []) as $file) { $order->files()->create(['file_type'=>$file->getClientOriginalExtension(),'file_url'=>$file->store("orders/{$order->id}",'private'),'uploaded_by'=>$request->user()->id]); } return redirect()->route('orders.show',$order)->with('success','Order created successfully.'); } public function show(Order $order): Response { $this->authorize('view',$order); return Inertia::render('Orders/Show', ['order'=>new OrderResource($order->load(['customer','worker','files','progressUpdates.creator','payments']))]); } }
